<?php $users=$pdo->query('SELECT id,username,role,created_at FROM users ORDER BY id DESC')->fetchAll(); ?><section class="glass-card"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><h2>Pengurusan Pengguna</h2><p class="muted">Tambah dan urus akaun sistem.</p></div><a class="btn btn-cyan" href="index.php?page=register-user">Tambah pengguna</a></div><div class="table-responsive"><table class="table table-dark table-hover align-middle"><thead><tr><th>Nama</th><th>Peranan</th><th>Tarikh daftar</th><th>Tindakan</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?=e($u['username'])?></td><td><?=e(strtoupper($u['role']))?></td><td><?=e($u['created_at'])?></td><td><?php if((int)$u['id']!==(int)$_SESSION['user']['id']): ?><form method="post" action="index.php?page=delete-user" onsubmit="return confirm('Padam akaun ini?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn btn-sm btn-outline-danger">Padam</button></form><?php else: ?><span class="muted">Akaun anda</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>